import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.YKbyQ3zk.js";const u=JSON.parse('{"title":"Quickstart: TanStack Start with the standalone server","description":"","frontmatter":{},"headers":[],"relativePath":"quickstart/tanstack-server.md","filePath":"quickstart/tanstack-server.md"}'),o={name:"quickstart/tanstack-server.md"};function n(r,e,d,h,l,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="quickstart-tanstack-start-with-the-standalone-server" tabindex="-1">Quickstart: TanStack Start with the standalone server <a class="header-anchor" href="#quickstart-tanstack-start-with-the-standalone-server" aria-label="Permalink to &quot;Quickstart: TanStack Start with the standalone server&quot;">​</a></h1><p>This page takes you from an empty folder to a TanStack Start app where you sign up with an email address and a password and land on a signed-in page. It uses the standalone Evo Auth server, which keeps its users in a SQLite file on your machine. You make no account anywhere and need no mail service or OAuth app.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><ul><li><strong>Node 26.3 or newer.</strong> The server uses Node&#39;s built-in SQLite.</li><li><strong>pnpm.</strong></li><li><strong>git.</strong> <code>init</code> refuses to run in a folder that is not a git repository, because it checks that git ignores the file it writes your secrets to.</li></ul><p>The commands below are for a Unix shell (macOS, Linux, or WSL). Run each block as a whole. Steps 7 and 8 each need their own terminal, so keep this one for the rest.</p><p>Step 2 installs from the npm registry, so it works once Evo Auth has been published there.</p><h2 id="the-steps" tabindex="-1">The steps <a class="header-anchor" href="#the-steps" aria-label="Permalink to &quot;The steps&quot;">​</a></h2><h3 id="1-create-the-app" tabindex="-1">1. Create the app <a class="header-anchor" href="#1-create-the-app" aria-label="Permalink to &quot;1. Create the app&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes evo-light evo-dark vp-code" tabindex="0"><code><span class="line"><span>pnpm create @tanstack/start@0.59.61 my-app --yes</span></span>
<span class="line"><span>cd my-app</span></span>
<span class="line"><span>test -d .git || git init</span></span></code></pre></div><p><code>--yes</code> accepts the create command&#39;s defaults and asks nothing. The create command may end with a line saying <code>@tanstack/intent install</code> did not run successfully: ignore it. The last line starts a git repository only if the create command did not.</p><h3 id="2-install-the-packages" tabindex="-1">2. Install the packages <a class="header-anchor" href="#2-install-the-packages" aria-label="Permalink to &quot;2. Install the packages&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes evo-light evo-dark vp-code" tabindex="0"><code><span class="line"><span>pnpm add @evo-auth/core@0.1.0 @evo-auth/react@0.1.0 @evo-auth/server@0.1.0</span></span></code></pre></div><h3 id="3-run-init" tabindex="-1">3. Run init <a class="header-anchor" href="#3-run-init" aria-label="Permalink to &quot;3. Run init&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes evo-light evo-dark vp-code" tabindex="0"><code><span class="line"><span>pnpm exec evo-auth init --stack tanstack-server</span></span></code></pre></div><p><code>init</code> writes these files and refuses, changing nothing, if any of them already exists:</p><ul><li><code>.env.local</code>, holding the signing keys and secrets it made. No other file holds a secret.</li><li><code>evo-auth.config.ts</code>: email and password sign-up, no provider, and a development sender that prints each code in a terminal instead of sending mail.</li><li><code>evo-auth.server.mjs</code>: the server&#39;s options. It loads <code>.env.local</code> and listens on <code>127.0.0.1:3001</code>.</li><li><code>src/lib/evo-auth.server.ts</code> and <code>src/routes/auth/$.ts</code>: the proxy that relays <code>/auth/*</code> from your app to the server.</li><li><code>src/middleware/evo-auth.ts</code>, and <code>src/start.ts</code> if your app has none: the request middleware. If your app already has a <code>src/start.ts</code>, <code>init</code> prints the one line to add to it.</li><li><code>src/components/evo-auth-root.tsx</code>, <code>src/routes/sign-in.tsx</code> and <code>src/routes/sign-up.tsx</code>.</li></ul><p>It then prints the edits it does not make itself. Steps 4 to 6 are those edits. It also prints a line for <code>.gitignore</code>, which keeps the server&#39;s database out of git. Add it now:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes evo-light evo-dark vp-code" tabindex="0"><code><span class="line"><span>echo &#39;evo-auth.sqlite*&#39; &gt;&gt; .gitignore</span></span></code></pre></div><h3 id="4-import-the-root-component" tabindex="-1">4. Import the root component <a class="header-anchor" href="#4-import-the-root-component" aria-label="Permalink to &quot;4. Import the root component&quot;">​</a></h3><p>In <code>src/routes/__root.tsx</code>, add this line with the other imports:</p><div class="language-tsx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">tsx</span><pre class="shiki shiki-themes evo-light evo-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A3FC0;--shiki-dark:#C3A6FF;">import</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;"> {</span><span style="--shiki-light:#1B1A18;--shiki-dark:#EFEEE9;"> EvoAuthRoot</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">,</span><span style="--shiki-light:#1B1A18;--shiki-dark:#EFEEE9;"> loadAuthState </span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">}</span><span style="--shiki-light:#6A3FC0;--shiki-dark:#C3A6FF;"> from</span><span style="--shiki-light:#17723F;--shiki-dark:#7FD6A4;"> &quot;../components/evo-auth-root&quot;</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">;</span></span></code></pre></div><h3 id="5-add-the-loader" tabindex="-1">5. Add the loader <a class="header-anchor" href="#5-add-the-loader" aria-label="Permalink to &quot;5. Add the loader&quot;">​</a></h3><p>In the same file, add these two lines to the options object that <code>createRootRoute</code> is called with, beside <code>head</code> and <code>shellComponent</code>:</p><div class="language-tsx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">tsx</span><pre class="shiki shiki-themes evo-light evo-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1B1A18;--shiki-dark:#EFEEE9;">loader</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">:</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;"> ()</span><span style="--shiki-light:#6A3FC0;--shiki-dark:#C3A6FF;"> =&gt;</span><span style="--shiki-light:#2A40B4;--shiki-dark:#A8B6FF;"> loadAuthState</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">(),</span></span>
<span class="line"><span style="--shiki-light:#1B1A18;--shiki-dark:#EFEEE9;">shouldReload</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">:</span><span style="--shiki-light:#6A3FC0;--shiki-dark:#C3A6FF;"> false</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">,</span></span></code></pre></div><h3 id="6-wrap-the-page" tabindex="-1">6. Wrap the page <a class="header-anchor" href="#6-wrap-the-page" aria-label="Permalink to &quot;6. Wrap the page&quot;">​</a></h3><p>In the same file, find the <code>&lt;body&gt;</code> in the root document. It renders <code>{children}</code>. Wrap that in <code>EvoAuthRoot</code>, and leave <code>&lt;Scripts /&gt;</code> after it:</p><div class="language-tsx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">tsx</span><pre class="shiki shiki-themes evo-light evo-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">&lt;</span><span style="--shiki-light:#9A4D00;--shiki-dark:#F0B65A;">EvoAuthRoot</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">&gt;{</span><span style="--shiki-light:#1B1A18;--shiki-dark:#EFEEE9;">children</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">}&lt;/</span><span style="--shiki-light:#9A4D00;--shiki-dark:#F0B65A;">EvoAuthRoot</span><span style="--shiki-light:#73716A;--shiki-dark:#85837B;">&gt;</span></span></code></pre></div><h3 id="7-start-the-auth-server" tabindex="-1">7. Start the auth server <a class="header-anchor" href="#7-start-the-auth-server" aria-label="Permalink to &quot;7. Start the auth server&quot;">​</a></h3><p>In a second terminal, in <code>my-app</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes evo-light evo-dark vp-code" tabindex="0"><code><span class="line"><span>cd my-app</span></span>
<span class="line"><span>pnpm exec evo-auth-server start</span></span></code></pre></div><p>It creates <code>evo-auth.sqlite</code> and listens on <code>http://127.0.0.1:3001</code>. Leave it running. This is the terminal where the sign-up code appears.</p><h3 id="8-start-the-app" tabindex="-1">8. Start the app <a class="header-anchor" href="#8-start-the-app" aria-label="Permalink to &quot;8. Start the app&quot;">​</a></h3><p>In a third terminal, in <code>my-app</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes evo-light evo-dark vp-code" tabindex="0"><code><span class="line"><span>cd my-app</span></span>
<span class="line"><span>pnpm dev</span></span></code></pre></div><h3 id="9-sign-up" tabindex="-1">9. Sign up <a class="header-anchor" href="#9-sign-up" aria-label="Permalink to &quot;9. Sign up&quot;">​</a></h3><p>Open <code>http://localhost:3000/sign-up</code>. Enter an email address and a password of at least 15 characters that is not a well-known phrase (the form shows both rules: it refuses a password found in a known data breach), and press <strong>Create account</strong>. The page asks for a code and stays on the same page: leave it open. The server&#39;s terminal from step 7 has printed a message with the code: type it in on that page and press <strong>Create account</strong> again. The page then says <strong>You are signed in</strong>.</p><h2 id="if-something-goes-wrong" tabindex="-1">If something goes wrong <a class="header-anchor" href="#if-something-goes-wrong" aria-label="Permalink to &quot;If something goes wrong&quot;">​</a></h2><ul><li><strong><code>init</code> says a file already exists.</strong> Move that file aside and run it again. <code>init</code> never overwrites or edits a file.</li><li><strong><code>init</code> says the env file is not ignored by git.</strong> Add <code>.env.local</code> to <code>.gitignore</code>, then run it again.</li><li><strong>The sign-up page shows an error about <code>evoAuthMiddleware</code>.</strong> The app&#39;s <code>src/start.ts</code> does not list the middleware: add the line <code>init</code> printed.</li><li><strong>No code appears in the server&#39;s terminal.</strong> The code is printed only by the terminal that runs <code>evo-auth-server start</code>, never the one that runs <code>pnpm dev</code>.</li></ul><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="./../handler-mounts.html">Handler mounts</a> and <a href="./../server.html">the standalone server</a> explain the files <code>init</code> wrote.</li><li><a href="./../email-password.html">Email and password</a> covers password rules and reset.</li><li><a href="./../email.html">Email codes and links</a> shows how to replace the development sender before you deploy.</li><li><a href="./../github-oauth-app.html">Register a GitHub OAuth app</a> adds GitHub sign-in.</li></ul>`,40)])])}const g=a(o,[["render",n]]);export{u as __pageData,g as default};
